            <CardContent className="flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <p className="text-xs font-semibold uppercase tracking-wider opacity-80">DAILY WORKFLOW COMMAND</p>
                <p className="mt-1 text-xl font-bold font-mono">npm run dev</p>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs opacity-80">Build & Package Installer:</span>
                <code className="rounded-md bg-black/25 px-3 py-1.5 text-xs font-mono font-semibold">npm run make</code>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* TAB 2: DATABASE STUDIO */}
      {activeTab === "database" && (
        <div className="animate-in fade-in duration-200">
          <DatabaseStudio />
        </div>
      )}

      {/* TAB 3: NATIVE OS PLAYGROUND */}
      {activeTab === "native" && (
        <div className="animate-in fade-in duration-200">
          <NativePlayground />
        </div>
      )}

      {/* TAB 4: SERVER RPC VERIFICATION */}
      {activeTab === "server" && (
        <div className="space-y-6 animate-in fade-in duration-200">
          <div>
            <h2 className="text-2xl font-bold tracking-tight flex items-center gap-2">
              <Server className="size-6 text-primary" /> Next.js Server-Side Verification
            </h2>
            <p className="text-xs text-muted-foreground mt-1 max-w-2xl">
              Verify that Route Handlers (<code>/api/...</code>) and Server Actions (<code>&quot;use server&quot;</code>) execute on the local desktop server after packaging.
            </p>
          </div>

          <div className="grid gap-6 md:grid-cols-2">
            {/* Card 1: API Route Handler */}
            <Card className="border border-border/80 bg-card/70 backdrop-blur-md">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="flex size-10 items-center justify-center rounded-xl bg-primary/10 text-primary">
                    <Cpu className="size-5" />
                  </div>
                  {apiLatency !== null && (
                    <span className="text-xs font-mono bg-primary/10 text-primary px-2.5 py-1 rounded-full border border-primary/20">
                      {apiLatency}ms latency
                    </span>
                  )}
                </div>
                <CardTitle className="mt-2 text-base">Next.js API Route Handler</CardTitle>
                <CardDescription className="text-xs">
                  Tests <code>/api/system</code> to verify Node.js server execution and HTTP routing.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-3">
                <Button
                  onClick={handleTestApi}
                  disabled={apiLoading}
                  className="w-full"
                  variant="outline"
                >
                  <Activity className="size-4 mr-2" />
                  {apiLoading ? "Testing Route Handler..." : "Test /api/system Route"}
                </Button>

                {apiData ? (
                  <div className="rounded-xl bg-muted/50 p-3.5 text-xs font-mono space-y-1.5 border border-border/40 select-text">
                    <div className="text-emerald-500 font-semibold">✓ Server Response (PID: {apiData.runtime.processId})</div>
                    <div>Node: {apiData.runtime.nodeVersion} ({apiData.runtime.arch})</div>
                    <div>Platform: {apiData.runtime.platform}</div>
                    <div>Memory: {apiData.runtime.memory}</div>
                    <div>Time: {new Date(apiData.timestamp).toLocaleTimeString()}</div>
                  </div>
                ) : (
                  <p className="text-xs text-muted-foreground text-center py-4">
                    Click to execute server-side Node.js route handler.
                  </p>
                )}
              </CardContent>
            </Card>

            {/* Card 2: Server Action */}
            <Card className="border border-border/80 bg-card/70 backdrop-blur-md">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="flex size-10 items-center justify-center rounded-xl bg-primary/10 text-primary">
                    <Zap className="size-5" />
                  </div>
                  {actionData && (
                    <span className="text-xs font-mono bg-emerald-500/10 text-emerald-500 px-2.5 py-1 rounded-full border border-emerald-500/20">
                      RPC Success
                    </span>
                  )}
                </div>
                <CardTitle className="mt-2 text-base">Next.js Server Action</CardTitle>
                <CardDescription className="text-xs">
                  Executes a <code>&quot;use server&quot;</code> function directly through Next.js RPC.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-3">
                <Button
                  onClick={handleTestServerAction}
                  disabled={isPending}
                  className="w-full"
                  variant="outline"
                >
                  <Zap className="size-4 mr-2" />
                  {isPending ? "Executing Action..." : "Run Server Action"}
                </Button>

                {actionData ? (
                  <div className="rounded-xl bg-muted/50 p-3.5 text-xs font-mono space-y-1.5 border border-border/40 select-text">
                    <div className="text-emerald-500 font-semibold">✓ Action Result (PID: {actionData.serverPid})</div>
                    <div>Output: {actionData.echoMessage}</div>
                    <div>Host: {actionData.serverHostname}</div>
                    <div>Processed: {actionData.processedAt}</div>
                  </div>
                ) : (
                  <p className="text-xs text-muted-foreground text-center py-4">
                    Click to trigger a Next.js Server Action RPC.
                  </p>
                )}
              </CardContent>
            </Card>
          </div>
        </div>
      )}

      {/* TAB 5: SETTINGS */}
      {activeTab === "settings" && (
        <div className="space-y-6 animate-in fade-in duration-200">
          <div>
            <h2 className="text-2xl font-bold tracking-tight flex items-center gap-2">
              <Settings className="size-6 text-primary" /> Application & Database Settings
            </h2>
            <p className="text-xs text-muted-foreground mt-1">
              Inspect application runtime, manage real-time database storage, and trigger maintenance tasks.
            </p>
          </div>

          <div className="grid gap-6 md:grid-cols-2">
            <Card className="border border-border/80 bg-card/70 backdrop-blur-md">
              <CardHeader>
                <CardTitle className="text-base">Database File Maintenance</CardTitle>
                <CardDescription className="text-xs">
                  Create timestamped backups, reveal the file in explorer, or reset demo data.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-3">
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full justify-start"
                  onClick={async () => {
                    try {
                      const p = await db.backup();
                      toast.success("Backup Created", p);
                    } catch (err) {
                      toast.error("Backup Failed", String(err));
                    }
                  }}
                >
                  <HardDrive className="size-4 mr-2 text-primary" /> Create Database Backup
                </Button>

                <Button
                  variant="outline"
                  size="sm"
                  className="w-full justify-start"
                  onClick={async () => {
                    try {
                      if (window.desktop?.shell && window.desktop?.db) {
                        const fp = await window.desktop.db.getFilePath();
                        await window.desktop.shell.showItemInFolder(fp);
                        toast.info("Revealed in Explorer", fp);
                      } else {
                        toast.info("Web Preview Mode", "File is in data/db.json");
                      }
                    } catch (err) {
                      toast.error("Action Failed", String(err));
                    }
                  }}
                >
                  <FolderOpen className="size-4 mr-2 text-sky-400" /> Reveal data/db.json in File Explorer
                </Button>

                <Button
                  variant="outline"
                  size="sm"
                  className="w-full justify-start text-rose-500 hover:text-rose-600"
                  onClick={async () => {
                    if (confirm("Are you sure you want to reset the database? This empties all collections.")) {
                      try {
                        await db.reset();
                        toast.info("Database Reset", "All collections have been cleared");
                      } catch (err) {
                        toast.error("Reset Failed", String(err));
                      }
                    }
                  }}
                >
                  <RefreshCw className="size-4 mr-2" /> Reset Database to Clean Slate
                </Button>
              </CardContent>
            </Card>

            <Card className="border border-border/80 bg-card/70 backdrop-blur-md">
              <CardHeader>
                <CardTitle className="text-base">About Nextron</CardTitle>
                <CardDescription className="text-xs">
                  Desktop starter kit architecture details and version info.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-3 text-xs">
                <div className="flex justify-between py-1.5 border-b border-border/40">
                  <span className="text-muted-foreground">Framework</span>
                  <span className="font-semibold">Next.js 16 (App Router)</span>
                </div>
                <div className="flex justify-between py-1.5 border-b border-border/40">
                  <span className="text-muted-foreground">Desktop Wrapper</span>
                  <span className="font-semibold">Electron 37</span>
                </div>
                <div className="flex justify-between py-1.5 border-b border-border/40">
                  <span className="text-muted-foreground">Styling</span>
                  <span className="font-semibold">Tailwind CSS 4 + shadcn/ui</span>
                </div>
                <div className="flex justify-between py-1.5 border-b border-border/40">
                  <span className="text-muted-foreground">Database Engine</span>
                  <span className="font-semibold text-emerald-500">Atomic Real-Time JSON</span>
                </div>
                <div className="flex justify-between py-1.5">
                  <span className="text-muted-foreground">Packaging Tool</span>
                  <span className="font-semibold">Electron Forge</span>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      )}
        </main>
      </div>
    </div>
  );
}

components/app-sidebar.tsx.content:
"use client";

import * as React from "react";
import {
  LayoutDashboard,
  Database,
  Cpu,
  Server,
  Settings,
  Sparkles,
  Layers,
  HardDrive,
  FolderGit2,
  ExternalLink,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar";
import { desktopConfig } from "@/lib/config";
import { useDatabaseStats } from "@/lib/db";

interface AppSidebarProps {
  activeTab: string;
  onTabChange: (tab: any) => void;
}

export function AppSidebar({ activeTab, onTabChange }: AppSidebarProps) {
  const { stats } = useDatabaseStats();

  const navItems = [
    { id: "overview", title: "Overview", icon: LayoutDashboard, badge: null },
    { id: "database", title: "Database Studio", icon: Database, badge: stats?.collections ? Object.values(stats.collections).reduce((a, b) => a + b, 0) : null },
    { id: "native", title: "Native OS", icon: Cpu, badge: "Desktop" },
    { id: "server", title: "Server RPC", icon: Server, badge: null },
    { id: "settings", title: "Settings", icon: Settings, badge: null },
  ];

  return (
    <Sidebar className="border-r border-border/50 bg-card/40 backdrop-blur-md">
      <SidebarHeader className="border-b border-border/40 p-4">
        <div className="flex items-center gap-3">
          <div className="flex size-8 items-center justify-center rounded-xl bg-primary text-primary-foreground font-bold shadow-md shadow-primary/20">
            <Sparkles className="size-4" />
          </div>
          <div className="flex flex-col">
            <span className="font-bold tracking-tight text-sm text-foreground">
              {desktopConfig.app.name}
            </span>
            <span className="text-[10px] font-mono text-muted-foreground">
              v{desktopConfig.app.version} • Next.js 16
            </span>
          </div>
        </div>
      </SidebarHeader>

      <SidebarContent className="p-3">
        <SidebarGroup>
          <SidebarGroupLabel className="text-[10px] font-semibold tracking-wider text-muted-foreground/70 uppercase">
            Platform Navigation
          </SidebarGroupLabel>
          <SidebarMenu className="mt-1 space-y-1">
            {navItems.map((item) => {
              const Icon = item.icon;
              const isActive = activeTab === item.id;
              return (
                <SidebarMenuItem key={item.id}>
                  <SidebarMenuButton
                    isActive={isActive}
                    onClick={() => onTabChange(item.id)}
                    className="cursor-pointer"
                  >
                    <Icon className="size-4 shrink-0" />
                    <span className="flex-1 font-medium">{item.title}</span>
                    {item.badge !== null && item.badge !== undefined && (
                      <span
                        className={`rounded-full px-2 py-0.5 text-[10px] font-mono ${
                          isActive
                            ? "bg-primary-foreground/20 text-primary-foreground font-semibold"
                            : "bg-muted text-muted-foreground"
                        }`}
                      >
                        {item.badge}
                      </span>
                    )}
                  </SidebarMenuButton>
                </SidebarMenuItem>
              );
            })}
          </SidebarMenu>
        </SidebarGroup>

        <SidebarGroup className="mt-4">
          <SidebarGroupLabel className="text-[10px] font-semibold tracking-wider text-muted-foreground/70 uppercase">
            Kit Resources
          </SidebarGroupLabel>
          <SidebarMenu className="mt-1 space-y-1">
            <SidebarMenuItem>
              <SidebarMenuButton
                onClick={() => {
                  if (typeof window !== "undefined" && window.desktop?.openExternal) {
                    window.desktop.openExternal("https://nextjs.org/docs");
                  } else {
                    window.open("https://nextjs.org/docs", "_blank");
                  }
                }}
                className="cursor-pointer text-muted-foreground hover:text-foreground"
              >
                <Layers className="size-4 shrink-0" />
                <span className="flex-1">Next.js 16 Docs</span>
                <ExternalLink className="size-3 text-muted-foreground/50" />
              </SidebarMenuButton>
            </SidebarMenuItem>

            <SidebarMenuItem>
              <SidebarMenuButton
                onClick={() => {
                  if (typeof window !== "undefined" && window.desktop?.openExternal) {
                    window.desktop.openExternal("https://www.electronjs.org/docs/latest");
                  } else {
                    window.open("https://www.electronjs.org/docs/latest", "_blank");
                  }
                }}
                className="cursor-pointer text-muted-foreground hover:text-foreground"
              >
                <Cpu className="size-4 shrink-0" />
                <span className="flex-1">Electron Guides</span>
                <ExternalLink className="size-3 text-muted-foreground/50" />
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-3">
        <div className="rounded-xl border border-border/50 bg-muted/40 p-3 space-y-1.5">
          <div className="flex items-center justify-between text-[11px] font-medium text-foreground">
            <span className="flex items-center gap-1.5">
              <HardDrive className="size-3.5 text-primary" /> Real-Time DB
            </span>
            <span className="font-mono text-[10px] text-emerald-500">Active</span>
          </div>
          <div className="flex justify-between text-[10px] font-mono text-muted-foreground">
            <span>Storage Engine:</span>
            <span>Zero-Promise Sync</span>
          </div>
          {stats && (
            <div className="flex justify-between text-[10px] font-mono text-muted-foreground">
              <span>Disk Size:</span>
              <span>{(stats.sizeBytes / 1024).toFixed(1)} KB</span>
            </div>
          )}
        </div>
      </SidebarFooter>
    </Sidebar>
  );
}

components/command-palette.tsx.content:
"use client";

import { useEffect, useState, useMemo } from "react";
import {
  Search,
  LayoutDashboard,
  Database,
  Cpu,
  Server,
  Settings,
  Sun,
  Moon,
  HardDrive,
  Bell,
  Volume2,
  Copy,
  FolderOpen,
  ArrowRight,
  Sparkles,
} from "lucide-react";
import { useTheme } from "@/components/theme-provider";
import { dbClient } from "@/lib/db/client";
import { toast } from "@/components/ui/toast";

interface CommandItem {
  id: string;
  category: "Navigation" | "Database" | "Native OS" | "Preferences";
  title: string;
  description?: string;
  icon: any;
  action: () => void | Promise<void>;
}

interface CommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  onNavigateTab?: (tab: "overview" | "database" | "native" | "server" | "settings") => void;
}

export function CommandPalette({ isOpen, onClose, onNavigateTab }: CommandPaletteProps) {
  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const { theme, setTheme } = useTheme();

  const commands: CommandItem[] = useMemo(() => {
    return [
      // Navigation
      {
        id: "nav-overview",
        category: "Navigation",
        title: "Go to Dashboard Overview",
        description: "View system vitals, metrics, and starter quick-steps",
        icon: LayoutDashboard,
        action: () => {
          onNavigateTab?.("overview");
          onClose();
        },
      },
      {
        id: "nav-database",
        category: "Navigation",
        title: "Go to Database Studio",
        description: "Manage real-time JSON collections, filter, sort, and export",
        icon: Database,
        action: () => {
          onNavigateTab?.("database");
          onClose();
        },
      },
      {
        id: "nav-native",
        category: "Navigation",
        title: "Go to Native OS Playground",
        description: "Test native file dialogs, OS notifications, and clipboard",
        icon: Cpu,
        action: () => {
          onNavigateTab?.("native");
          onClose();
        },
      },
      {
        id: "nav-server",
        category: "Navigation",
        title: "Go to Server RPC Verification",
        description: "Test Route Handlers and Server Actions latency",
        icon: Server,
        action: () => {
          onNavigateTab?.("server");
          onClose();
        },
      },
      {
        id: "nav-settings",
        category: "Navigation",
        title: "Go to App Settings",
        description: "Configure app theme, data directory, and maintenance",
        icon: Settings,
        action: () => {
          onNavigateTab?.("settings");
          onClose();
        },
      },

      // Database Actions
      {
        id: "db-backup",
        category: "Database",
        title: "Create Database Backup",
        description: "Creates an atomic timestamped snapshot in data/backups/",
        icon: HardDrive,
        action: async () => {
          try {
            const backupPath = await dbClient.backup();
            toast.success("Database Backup Created", backupPath ? backupPath.split(/[/\\]/).pop() : "Saved to backups");
          } catch (err) {
            toast.error("Backup Failed", String(err));
          }
          onClose();
        },
      },
      {
        id: "db-export",
        category: "Database",
        title: "Export 'todos' Collection as JSON",
        description: "Copies current JSON data to clipboard",
        icon: Copy,
        action: async () => {
          try {
            const json = await dbClient.collection("todos").exportJson();
            if (window.desktop?.clipboard) {
              await window.desktop.clipboard.writeText(json);
              toast.success("Exported to Clipboard", "Todos JSON copied to clipboard");
            } else if (navigator.clipboard) {
              await navigator.clipboard.writeText(json);
              toast.success("Exported to Clipboard", "Todos JSON copied to clipboard");
            }
          } catch (err) {
            toast.error("Export Failed", String(err));
          }
          onClose();
        },
      },
      {
        id: "db-reveal",
        category: "Database",
        title: "Reveal Database File in Explorer / Finder",
        description: "Opens system file manager highlighting db.json",
        icon: FolderOpen,
        action: async () => {
          try {
            if (window.desktop?.shell && window.desktop?.db) {
              const filePath = await window.desktop.db.getFilePath();
              await window.desktop.shell.showItemInFolder(filePath);
              toast.info("Revealed in Explorer", filePath);
            } else {
              toast.info("Web Preview Mode", "Database file is located in project data/db.json");
            }
          } catch (err) {
            toast.error("Action Failed", String(err));
          }
          onClose();
        },
      },

      // Native OS Actions
      {
        id: "os-notification",
        category: "Native OS",
        title: "Trigger Native OS Notification",
        description: "Fires an operating system desktop notification banner",
        icon: Bell,
        action: async () => {
          if (window.desktop?.notification) {
            await window.desktop.notification.show("Nextron Desktop", "Native OS Notification received successfully!");
            toast.success("Notification Triggered");
          } else {
            toast.info("Native OS feature", "Only active inside the Electron desktop window.");
          }
          onClose();
        },
      },
      {
        id: "os-beep",
        category: "Native OS",
        title: "Play System Audio Beep",
        description: "Triggers the native system sound alert",
        icon: Volume2,
        action: async () => {
          if (window.desktop?.shell) {
            await window.desktop.shell.beep();
            toast.info("System Beep Executed");
          } else {
            toast.info("Native OS feature", "Only active inside the Electron desktop window.");
          }
          onClose();
        },
      },
      {
        id: "os-pin",
        category: "Native OS",
        title: "Toggle Window Always On Top",
        description: "Pins or unpins the application window above other windows",
        icon: Sparkles,
        action: async () => {
          if (window.desktop?.window) {
            const isCurrentlyOnTop = await window.desktop.window.isAlwaysOnTop();
            const newState = await window.desktop.window.setAlwaysOnTop(!isCurrentlyOnTop);
            toast.success(newState ? "Window Pinned on Top" : "Window Unpinned");
          } else {
            toast.info("Native OS feature", "Only active inside the Electron desktop window.");
          }
          onClose();
        },
      },

      // Preferences
      {
        id: "pref-theme",
        category: "Preferences",
        title: theme === "dark" ? "Switch to Light Theme" : "Switch to Dark Theme",
        description: "Toggle application colors and sync with native desktop chrome",
        icon: theme === "dark" ? Sun : Moon,
        action: () => {
          const nextTheme = theme === "dark" ? "light" : "dark";
          setTheme(nextTheme);
          if (window.desktop?.theme) {
            window.desktop.theme.setTheme(nextTheme);
          }
          toast.info("Theme Switched", `Active theme is now ${nextTheme}`);
          onClose();
        },
      },
    ];
  }, [theme, setTheme, onNavigateTab, onClose]);

  const filtered = useMemo(() => {
    if (!query.trim()) return commands;
    const term = query.toLowerCase().trim();
    return commands.filter(
      (c) =>
        c.title.toLowerCase().includes(term) ||
        (c.description && c.description.toLowerCase().includes(term)) ||
        c.category.toLowerCase().includes(term)
    );
  }, [commands, query]);

  // Global shortcut (Cmd+K / Ctrl+K)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        if (isOpen) onClose();
        else onNavigateTab?.("overview"); // Open palette trigger
      } else if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose, onNavigateTab]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center pt-20 px-4 bg-black/60 backdrop-blur-xs animate-in fade-in"
      onClick={onClose}
    >
      <div
        className="w-full max-w-xl overflow-hidden rounded-2xl border border-border/80 bg-card/95 backdrop-blur-xl shadow-2xl animate-in zoom-in-95 duration-150"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Search Input Bar */}
        <div className="flex items-center gap-3 border-b border-border/50 px-4 py-3.5">
          <Search className="size-4 text-primary shrink-0" />
          <input
            type="text"
            className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground select-text"
            placeholder="Type a command, action, or view to jump..."
            value={query}
            autoFocus
            onChange={(e) => {
              setQuery(e.target.value);
              setSelectedIndex(0);
            }}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown") {
                e.preventDefault();
                setSelectedIndex((prev) => (prev + 1) % (filtered.length || 1));
              } else if (e.key === "ArrowUp") {
                e.preventDefault();
                setSelectedIndex((prev) => (prev - 1 + filtered.length) % (filtered.length || 1));
              } else if (e.key === "Enter" && filtered[selectedIndex]) {
                e.preventDefault();
                void filtered[selectedIndex].action();
              }
            }}
          />
          <kbd className="rounded border border-border/80 bg-muted/60 px-1.5 py-0.5 text-[10px] font-mono text-muted-foreground">
            ESC
          </kbd>
        </div>

        {/* Results List */}
        <div className="max-h-80 overflow-y-auto p-2 space-y-1">
          {filtered.length === 0 ? (
            <div className="py-8 text-center text-xs text-muted-foreground">
              No matching commands found for &quot;{query}&quot;.
            </div>
          ) : (
            filtered.map((item, idx) => {
              const Icon = item.icon;
              const isSelected = idx === selectedIndex;
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => void item.action()}
                  onMouseEnter={() => setSelectedIndex(idx)}
                  className={`flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-left text-xs transition-colors ${
                    isSelected ? "bg-primary text-primary-foreground font-medium" : "text-foreground hover:bg-muted/60"
                  }`}
                >
                  <div className="flex items-center gap-3 min-w-0">
                    <div
                      className={`flex size-7 items-center justify-center rounded-lg ${
                        isSelected ? "bg-white/20 text-white" : "bg-muted text-primary"
                      }`}
                    >
                      <Icon className="size-3.5" />
                    </div>
                    <div className="min-w-0">
                      <p className="truncate font-semibold">{item.title}</p>
                      {item.description && (
                        <p className={`text-[10px] truncate ${isSelected ? "text-white/80" : "text-muted-foreground"}`}>
                          {item.description}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-1.5 shrink-0 pl-2">
                    <span
                      className={`rounded px-1.5 py-0.5 text-[9px] font-mono uppercase tracking-wider ${
                        isSelected ? "bg-white/20 text-white" : "bg-muted/80 text-muted-foreground"
                      }`}
                    >
                      {item.category}
                    </span>
                    {isSelected && <ArrowRight className="size-3 text-white" />}
                  </div>
                </button>
              );
            })
          )}
        </div>

        {/* Footer shortcuts */}
        <div className="flex items-center justify-between border-t border-border/40 bg-muted/30 px-4 py-2 text-[10px] text-muted-foreground">
          <div className="flex items-center gap-3">
            <span>
              <kbd className="font-mono bg-muted px-1 py-0.5 rounded border">↑</kbd> <kbd className="font-mono bg-muted px-1 py-0.5 rounded border">↓</kbd> navigate
            </span>
            <span>
              <kbd className="font-mono bg-muted px-1 py-0.5 rounded border">↵</kbd> select
            </span>
          </div>
          <span>Nextron Command System</span>
        </div>
      </div>
    </div>
  );
}

components/database-panel.tsx.content:
"use client";

import { useState, useTransition } from "react";
import { useIsClient } from "@/lib/utils";
import {
  Database,
  Radio,
  Plus,
  Trash2,
  CheckCircle2,
  Circle,
  HardDrive,
  Cpu,
  Zap,
  Server,
  FileJson,
  Layers,
  Sparkles,
  RefreshCw,
  FolderOpen,
} from "lucide-react";
import { useCollection, useDatabaseStats, isDesktopApp, db } from "@/lib/db";
import { createTodoServerAction, deleteTodoServerAction, toggleTodoServerAction } from "@/app/actions/db-action";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";

type TodoItem = {
  id: string;
  title: string;
  completed: boolean;
  priority?: "low" | "medium" | "high";
  source?: string;
  createdAt: string;
  updatedAt: string;
};

export function DatabasePanel() {
  const { data: todos, loading, insert, remove, update, refresh } = useCollection<TodoItem>("todos");
  const { stats, refresh: refreshStats } = useDatabaseStats();

  const [inputTitle, setInputTitle] = useState("");
  const [priority, setPriority] = useState<"low" | "medium" | "high">("medium");
  const [activeTab, setActiveTab] = useState<"client" | "serverAction" | "apiRoute" | "electron">("client");
  const [isPending, startTransition] = useTransition();
  const [showRawJson, setShowRawJson] = useState(false);
  const [lastActionLog, setLastActionLog] = useState<string>("System ready. Real-time sync active.");

  const isClient = useIsClient();
  const isDesktop = isClient && isDesktopApp();

  const handleAddViaClient = async () => {
    if (!inputTitle.trim()) return;
    try {
      const created = await insert({
        title: inputTitle.trim(),
        completed: false,
        priority,
        source: isDesktop ? "Client (Electron IPC)" : "Client (Web SDK)",
      });
      setLastActionLog(`Created "${created.title}" via Client Hook at ${new Date().toLocaleTimeString()}`);
      setInputTitle("");
    } catch (err) {
      setLastActionLog(`Client insert error: ${String(err)}`);
    }
  };

  const handleAddViaServerAction = () => {
    if (!inputTitle.trim()) return;
    startTransition(async () => {
      try {
        const res = await createTodoServerAction(inputTitle.trim(), priority);
        if (res.success && res.todo) {
          setLastActionLog(`Created "${res.todo.title}" via Next.js Server Action at ${new Date().toLocaleTimeString()}`);
          setInputTitle("");
        }
      } catch (err) {
        setLastActionLog(`Server Action error: ${String(err)}`);
      }
    });
  };

  const handleAddViaApiRoute = async () => {
    if (!inputTitle.trim()) return;
    try {
      const res = await fetch("/api/db", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "insert",
          collection: "todos",
          data: {
            title: inputTitle.trim(),
            completed: false,
            priority,
            source: "Next.js Route Handler (/api/db)",
          },
        }),
      });
      const json = await res.json();
      if (json.success) {
        setLastActionLog(`Created "${json.data.title}" via /api/db Route at ${new Date().toLocaleTimeString()}`);
        setInputTitle("");
      }
    } catch (err) {
      setLastActionLog(`API Route error: ${String(err)}`);
    }
  };

  const handleAddViaElectron = async () => {
    if (!inputTitle.trim()) return;
    try {
      if (window.desktop?.db) {
        const created = await window.desktop.db.insert("todos", {
          title: inputTitle.trim(),
          completed: false,
          priority,
          source: "Direct Electron IPC Main",
        });
        setLastActionLog(`Created "${created.title}" via Direct Electron IPC at ${new Date().toLocaleTimeString()}`);
        setInputTitle("");
      } else {
        setLastActionLog("Direct Electron IPC is only active inside the desktop window.");
      }
    } catch (err) {
      setLastActionLog(`Electron IPC error: ${String(err)}`);
    }
  };

  const handleToggle = async (todo: TodoItem) => {
    if (activeTab === "serverAction") {
      startTransition(async () => {
        await toggleTodoServerAction(todo.id, !todo.completed);
        setLastActionLog(`Toggled "${todo.title}" via Server Action`);
      });
    } else {
      await update(todo.id, { completed: !todo.completed });
      setLastActionLog(`Toggled "${todo.title}" via Real-Time DB`);
    }
  };

  const handleDelete = async (id: string, title: string) => {
    if (activeTab === "serverAction") {
      startTransition(async () => {
        await deleteTodoServerAction(id);
        setLastActionLog(`Deleted "${title}" via Server Action`);
      });
    } else {
      await remove(id);
      setLastActionLog(`Deleted "${title}" via Real-Time DB`);
    }
  };

  return (
    <Card className="border border-border/80 bg-card/60 backdrop-blur-md shadow-xl overflow-hidden">
      {/* Header Banner */}
      <CardHeader className="border-b border-border/40 bg-muted/20 pb-4">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="flex size-8 items-center justify-center rounded-lg bg-primary/10 text-primary">
                <Database className="size-4" />
              </span>
              <CardTitle className="text-xl font-bold tracking-tight">
                All-in-One Real-Time JSON Database
              </CardTitle>
              <span className="inline-flex items-center gap-1 rounded-full bg-emerald-500/10 px-2.5 py-0.5 text-xs font-medium text-emerald-500">
                <Radio className="size-3 animate-pulse" /> Live Sync Active
              </span>
            </div>
            <CardDescription className="text-xs">
              Automatic zero-config storage in application directory (<code>app.getAppPath()</code>). Shared across Electron Main, Next.js Server, and Client React components in real time.
            </CardDescription>
          </div>

          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                refresh();
                refreshStats();
              }}
              title="Refresh database state"
            >
              <RefreshCw className="size-3.5 mr-1.5" /> Sync
            </Button>
            <Button
              variant={showRawJson ? "default" : "outline"}
              size="sm"
              onClick={() => setShowRawJson(!showRawJson)}
            >
              <FileJson className="size-3.5 mr-1.5" /> {showRawJson ? "Hide JSON" : "Inspect db.json"}
            </Button>
          </div>
        </div>

        {/* Database Directory & Stats Bar */}
        <div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4 rounded-lg bg-muted/40 p-2.5 text-xs font-mono border border-border/30">
          <div className="flex items-center gap-1.5 truncate">
            <FolderOpen className="size-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground truncate" title={stats?.filePath || "data/db.json"}>
              {stats?.filePath ? stats.filePath.split(/[/\\]/).slice(-2).join("/") : "data/db.json"}
            </span>
          </div>
          <div className="flex items-center gap-1.5">
            <HardDrive className="size-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground">Size:</span>
            <span className="font-semibold">{stats ? `${stats.sizeBytes} B` : "0 B"}</span>
          </div>
          <div className="flex items-center gap-1.5">
            <Layers className="size-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground">Revision:</span>
            <span className="font-semibold">v{stats?.rev || 0}</span>
          </div>
          <div className="flex items-center gap-1.5">
            <Sparkles className="size-3.5 text-emerald-500 shrink-0" />
            <span className="text-muted-foreground">Mode:</span>
            <span className="text-emerald-500 font-semibold">{isDesktop ? "Electron Native" : "Web Preview"}</span>
          </div>
        </div>
      </CardHeader>

      <CardContent className="p-6 space-y-6">
        {/* Raw JSON Inspector View */}
        {showRawJson && (
          <div className="rounded-xl border border-primary/20 bg-black/60 p-4 font-mono text-xs text-emerald-400 space-y-2">
            <div className="flex items-center justify-between text-muted-foreground pb-2 border-b border-border/40">
              <span className="flex items-center gap-2">
                <FileJson className="size-4 text-primary" /> Live file contents: {stats?.filePath || "db.json"}
              </span>
              <span className="text-[10px] text-muted-foreground">Auto-updates on change</span>
            </div>
            <pre className="max-h-60 overflow-y-auto whitespace-pre-wrap select-all">
              {JSON.stringify({ stats, todos }, null, 2)}
            </pre>
          </div>
        )}

        {/* Multi-Access Layer Switcher */}
        <div>
          <div className="mb-2 flex items-center justify-between">
            <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground flex items-center gap-1.5">
              <span>Test Real-Time Access Layers:</span>
            </label>
            <span className="text-xs text-muted-foreground font-mono">
              {todos.length} {todos.length === 1 ? "item" : "items"} in collection
            </span>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
            <Button
              type="button"
              variant={activeTab === "client" ? "default" : "outline"}
              size="sm"
              className="justify-start h-auto py-2.5 px-3"
              onClick={() => setActiveTab("client")}
            >
              <Cpu className="size-4 mr-2 shrink-0 text-cyan-400" />
              <div className="text-left">
                <div className="text-xs font-semibold">1. Client Hook</div>
                <div className="text-[10px] opacity-75">useDatabase()</div>
              </div>
            </Button>

            <Button
              type="button"
              variant={activeTab === "serverAction" ? "default" : "outline"}
              size="sm"
              className="justify-start h-auto py-2.5 px-3"
              onClick={() => setActiveTab("serverAction")}
            >
              <Zap className="size-4 mr-2 shrink-0 text-amber-400" />
              <div className="text-left">
                <div className="text-xs font-semibold">2. Server Action</div>
                <div className="text-[10px] opacity-75">&quot;use server&quot; RPC</div>
              </div>
            </Button>

            <Button
              type="button"
              variant={activeTab === "apiRoute" ? "default" : "outline"}
              size="sm"
              className="justify-start h-auto py-2.5 px-3"
              onClick={() => setActiveTab("apiRoute")}
            >
              <Server className="size-4 mr-2 shrink-0 text-indigo-400" />
              <div className="text-left">
                <div className="text-xs font-semibold">3. Route Handler</div>
                <div className="text-[10px] opacity-75">/api/db endpoint</div>
              </div>
            </Button>

            <Button
              type="button"
              variant={activeTab === "electron" ? "default" : "outline"}
              size="sm"
              className="justify-start h-auto py-2.5 px-3"
              onClick={() => setActiveTab("electron")}
            >
              <HardDrive className="size-4 mr-2 shrink-0 text-emerald-400" />
              <div className="text-left">
                <div className="text-xs font-semibold">4. Electron IPC</div>
                <div className="text-[10px] opacity-75">Main Process Bridge</div>
              </div>
            </Button>
          </div>
        </div>

        {/* Input Bar */}
        <div className="flex flex-col sm:flex-row gap-2">
          <input
            type="text"
            className="flex-1 rounded-lg border border-input bg-background/80 px-3.5 py-2 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring placeholder:text-muted-foreground"
            placeholder="Type a task or document to store in JSON database..."
            value={inputTitle}
            onChange={(e) => setInputTitle(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                if (activeTab === "client") void handleAddViaClient();
                else if (activeTab === "serverAction") handleAddViaServerAction();
                else if (activeTab === "apiRoute") void handleAddViaApiRoute();
                else if (activeTab === "electron") void handleAddViaElectron();
              }
            }}
          />

          <select
            className="rounded-lg border border-input bg-background/80 px-3 py-2 text-xs font-medium shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            value={priority}
            onChange={(e) => setPriority(e.target.value as "low" | "medium" | "high")}
          >
            <option value="low">Low Priority</option>
            <option value="medium">Medium Priority</option>
            <option value="high">High Priority</option>
          </select>

          <Button
            type="button"
            disabled={isPending || !inputTitle.trim()}
            onClick={() => {
              if (activeTab === "client") void handleAddViaClient();
              else if (activeTab === "serverAction") handleAddViaServerAction();
              else if (activeTab === "apiRoute") void handleAddViaApiRoute();
              else if (activeTab === "electron") void handleAddViaElectron();
            }}
            className="shrink-0"
          >
            <Plus className="size-4 mr-1.5" />
            {isPending ? "Executing..." : "Save to Database"}
          </Button>
        </div>

        {/* Real-time Todo/Item List */}
        <div className="space-y-2">
          {loading ? (
            <div className="py-8 text-center text-xs text-muted-foreground animate-pulse">
              Loading database collection...
            </div>
          ) : todos.length === 0 ? (
            <div className="rounded-xl border border-dashed p-8 text-center space-y-2">
              <Database className="size-8 mx-auto text-muted-foreground/50" />
              <p className="text-sm font-medium text-muted-foreground">The database collection is empty.</p>
              <p className="text-xs text-muted-foreground">Add your first item above to see instant real-time sync across Electron & Next.js.</p>
            </div>
          ) : (
            <div className="space-y-2 max-h-80 overflow-y-auto pr-1">
              {todos.map((todo) => (
                <div
                  key={todo.id}
                  className={`flex items-center justify-between rounded-lg border p-3 transition-all ${
                    todo.completed
                      ? "bg-muted/30 border-border/40 opacity-70"
                      : "bg-background/60 border-border hover:border-primary/40 shadow-sm"
                  }`}
                >
                  <div className="flex items-center gap-3 min-w-0 flex-1 mr-3">
                    <button
                      type="button"
                      onClick={() => void handleToggle(todo)}
                      className="text-muted-foreground hover:text-primary transition-colors shrink-0"
                      title={todo.completed ? "Mark active" : "Mark completed"}
                    >
                      {todo.completed ? (
                        <CheckCircle2 className="size-5 text-emerald-500" />
                      ) : (
                        <Circle className="size-5" />
                      )}
                    </button>
                    <div className="min-w-0 flex-1">
                      <p
                        className={`text-sm font-medium truncate ${
                          todo.completed ? "line-through text-muted-foreground" : "text-foreground"
                        }`}
                      >
                        {todo.title}
                      </p>
                      <div className="flex flex-wrap items-center gap-2 mt-0.5 text-[10px] text-muted-foreground">
                        <span className="font-mono bg-muted/60 px-1.5 py-0.2 rounded">{todo.id}</span>
                        {todo.source && (
                          <span className="rounded bg-primary/10 text-primary px-1.5 py-0.2 font-medium">
                            {todo.source}
                          </span>
                        )}
                        <span>{new Date(todo.createdAt).toLocaleTimeString()}</span>
                      </div>
                    </div>
                  </div>

                  <Button
                    variant="ghost"
                    size="icon"
                    className="size-8 text-muted-foreground hover:text-destructive shrink-0"
                    onClick={() => void handleDelete(todo.id, todo.title)}
                    title="Delete item"
                  >
                    <Trash2 className="size-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Live Event Activity Log */}
        <div className="rounded-lg bg-black/40 border border-border/40 p-3 text-xs font-mono space-y-1">
          <div className="flex items-center justify-between text-muted-foreground pb-1">
            <span className="flex items-center gap-1.5">
              <span className="size-2 rounded-full bg-emerald-500 animate-ping" />
              Live Activity Stream:
            </span>
            <span className="text-[10px]">Real-time Event Bridge</span>
          </div>
          <p className="text-emerald-400 font-medium truncate">{lastActionLog}</p>
        </div>
      </CardContent>
    </Card>
  );
}

components/database-studio.tsx.content:
"use client";

import { useState, useTransition, useMemo } from "react";
import {
  Database,
  Search,
  Plus,
  Trash2,
  CheckCircle2,
  Circle,
  FileJson,
  FileSpreadsheet,
  Download,
  Upload,
  HardDrive,
  RefreshCw,
  FolderOpen,
  Sparkles,
  Layers,
  ArrowUpDown,
  Filter,
  Eye,
  SlidersHorizontal,
} from "lucide-react";
import { useCollection, useDatabaseStats, isDesktopApp, db } from "@/lib/db";
import { useIsClient } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "@/components/ui/toast";

export function DatabaseStudio() {
  const isClient = useIsClient();
  const isDesktop = isClient && isDesktopApp();

  const [activeCollection, setActiveCollection] = useState("todos");
  const [searchTerm, setSearchTerm] = useState("");
  const [priorityFilter, setPriorityFilter] = useState<string>("all");
  const [sortField, setSortField] = useState<string>("createdAt");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");
  const [viewMode, setViewMode] = useState<"table" | "json">("table");

  // Input states
  const [newTitle, setNewTitle] = useState("");
  const [newPriority, setNewPriority] = useState<"low" | "medium" | "high">("medium");
  const [isPending, startTransition] = useTransition();

  // Query filter construction
  const queryFilter = useMemo(() => {
    const f: Record<string, any> = {};
    if (searchTerm.trim()) f._search = searchTerm.trim();
    if (priorityFilter !== "all") f.priority = priorityFilter;
    return Object.keys(f).length > 0 ? f : undefined;
  }, [searchTerm, priorityFilter]);

  const queryOptions = useMemo(() => {
    return {
      sort: sortField,
      order: sortOrder,
    };
  }, [sortField, sortOrder]);

  type StudioItem = {
    id: string;
    title?: string;
    name?: string;
    text?: string;
    completed?: boolean;
    priority?: "low" | "medium" | "high";
    source?: string;
    createdAt: string;
    updatedAt: string;
    [key: string]: any;
  };

  const { data: items, loading, insert, insertMany, update, remove, clear, refresh } = useCollection<StudioItem>(
    activeCollection,
    queryFilter,
    queryOptions
  );

  const { stats, refresh: refreshStats } = useDatabaseStats();

  const handleCreate = async () => {
    if (!newTitle.trim()) return;
    try {
      await insert({
        title: newTitle.trim(),
        completed: false,
        priority: newPriority,
        source: isDesktop ? "Electron Native Studio" : "Web Studio",
      });
      setNewTitle("");
      toast.success("Document Created", `Added "${newTitle.trim()}" to ${activeCollection}`);
    } catch (err) {
      toast.error("Creation Failed", String(err));
    }
  };

  const handleInsertSeedData = async () => {
    try {
      const seed = [
        { title: "Review architectural specifications", completed: true, priority: "high", source: "Seed Data" },
        { title: "Test Native OS File Dialogs", completed: false, priority: "high", source: "Seed Data" },
        { title: "Verify Server Actions RPC latency", completed: false, priority: "medium", source: "Seed Data" },
        { title: "Package installer with Electron Forge", completed: false, priority: "low", source: "Seed Data" },
      ];
      await insertMany(seed);
      toast.success("Seed Data Inserted", "Added 4 demo records into database");
    } catch (err) {
      toast.error("Seed Insert Failed", String(err));
    }
  };

  const handleToggle = async (item: any) => {
    try {
      await update(item.id, { completed: !item.completed });
    } catch (err) {
      toast.error("Update Failed", String(err));
    }
  };

  const handleDelete = async (id: string, title?: string) => {
    try {
      await remove(id);
      toast.info("Deleted Record", title ? `Removed "${title}"` : `Removed record ${id}`);
    } catch (err) {
      toast.error("Delete Failed", String(err));
    }
  };

  const handleExportJson = async () => {
    try {
      const json = await db.collection(activeCollection).exportJson();
      if (window.desktop?.dialog && window.desktop?.shell) {
        const saveRes = await window.desktop.dialog.showSaveDialog({
          title: `Export ${activeCollection}.json`,
          defaultPath: `${activeCollection}.json`,
          filters: [{ name: "JSON File", extensions: ["json"] }],
        });
        if (!saveRes.canceled && saveRes.filePath) {
          // Write via browser download or clipboard fallback
          const blob = new Blob([json], { type: "application/json" });
          const url = URL.createObjectURL(blob);
          const a = document.createElement("a");
          a.href = url;
          a.download = `${activeCollection}.json`;
          a.click();
          URL.revokeObjectURL(url);
          toast.success("Export Complete", `Saved ${activeCollection}.json`);
          return;
        }
      }

      const blob = new Blob([json], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${activeCollection}.json`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success("Export Complete", `Downloaded ${activeCollection}.json`);
    } catch (err) {
      toast.error("Export Failed", String(err));
    }
  };

  const handleExportCsv = async () => {
    try {
      const csv = await db.collection(activeCollection).exportCsv();
      const blob = new Blob([csv], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${activeCollection}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success("Export Complete", `Downloaded ${activeCollection}.csv`);
    } catch (err) {
      toast.error("Export Failed", String(err));
    }
  };

  const handleBackup = async () => {
    try {
      const backupPath = await db.backup();
      toast.success("Backup Created", backupPath ? backupPath.split(/[/\\]/).pop() : "Saved to data/backups");
    } catch (err) {
      toast.error("Backup Failed", String(err));
    }
  };

  const handleRevealFile = async () => {
    try {
      if (window.desktop?.shell && window.desktop?.db) {
        const filePath = await window.desktop.db.getFilePath();
        await window.desktop.shell.showItemInFolder(filePath);
        toast.info("Opened Explorer", filePath);
      } else {
        toast.info("Web Preview Mode", "Database file is located in project data/db.json");
      }
    } catch (err) {
      toast.error("Reveal Failed", String(err));
    }
  };

  const handleClearCollection = async () => {
    if (confirm(`Are you sure you want to clear all records from "${activeCollection}"?`)) {
      try {
        await clear();
        toast.info("Collection Cleared", `All records removed from ${activeCollection}`);
      } catch (err) {
        toast.error("Clear Failed", String(err));
      }
    }
  };

  return (
    <Card className="border border-border/80 bg-card/70 backdrop-blur-md shadow-2xl overflow-hidden">
      {/* Studio Header */}
      <CardHeader className="border-b border-border/40 bg-muted/20 pb-4">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="flex size-8 items-center justify-center rounded-lg bg-primary/10 text-primary">
                <Database className="size-4" />
              </span>
              <CardTitle className="text-xl font-bold tracking-tight">Database Studio</CardTitle>
              <span className="inline-flex items-center gap-1 rounded-full bg-emerald-500/10 px-2.5 py-0.5 text-xs font-medium text-emerald-500 border border-emerald-500/20">
                <span className="size-1.5 rounded-full bg-emerald-500 animate-pulse" /> Live Shared File
              </span>
            </div>
            <CardDescription className="text-xs">
              Zero-config, atomic real-time JSON engine synchronized across Next.js server, Electron main, and client hooks.
            </CardDescription>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handleBackup}
              title="Create a timestamped backup in data/backups/"
            >
              <HardDrive className="size-3.5 mr-1.5 text-primary" /> Backup DB
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={handleRevealFile}
              title="Reveal database file in system file explorer"
            >
              <FolderOpen className="size-3.5 mr-1.5 text-sky-400" /> Reveal File
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                refresh();
                refreshStats();
                toast.info("Database Synced", "Refreshed live state from disk");
              }}
              title="Force sync state"
            >
              <RefreshCw className="size-3.5 mr-1.5" /> Sync
            </Button>
          </div>
        </div>

        {/* Database Live Stats Strip */}
        <div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4 rounded-xl bg-muted/40 p-2.5 text-xs font-mono border border-border/30">
          <div className="flex items-center gap-1.5 truncate">
            <FolderOpen className="size-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground truncate" title={stats?.filePath || "data/db.json"}>
              {stats?.filePath ? stats.filePath.split(/[/\\]/).slice(-2).join("/") : "data/db.json"}
            </span>
          </div>
          <div className="flex items-center gap-1.5">
            <HardDrive className="size-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground">Size:</span>
            <span className="font-semibold">{stats ? `${stats.sizeBytes} B` : "0 B"}</span>
          </div>
          <div className="flex items-center gap-1.5">
            <Layers className="size-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground">Rev:</span>
            <span className="font-semibold">v{stats?.rev || 0}</span>
          </div>
          <div className="flex items-center gap-1.5">
            <Sparkles className="size-3.5 text-emerald-500 shrink-0" />
            <span className="text-muted-foreground">Mode:</span>
            <span className="text-emerald-500 font-semibold">{isDesktop ? "Electron Native" : "Web Preview"}</span>
          </div>
        </div>
      </CardHeader>

      <CardContent className="p-6 space-y-6">
        {/* Controls Toolbar: Collections, View Switcher, Export/Import */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between pb-2 border-b border-border/40">
          {/* Collection Switcher */}
          <div className="flex items-center gap-1.5">
            <span className="text-xs font-semibold text-muted-foreground mr-1">Collection:</span>
            {["todos", "notes", "settings", "logs"].map((col) => (
              <button
                key={col}
                type="button"
                onClick={() => setActiveCollection(col)}
                className={`rounded-lg px-2.5 py-1 text-xs font-medium transition-colors ${
                  activeCollection === col
                    ? "bg-primary text-primary-foreground font-semibold shadow-xs"
                    : "bg-muted/50 text-muted-foreground hover:bg-muted hover:text-foreground"
                }`}
              >
                {col}
                {stats?.collections?.[col] !== undefined && (
                  <span className="ml-1.5 opacity-75 font-mono text-[10px]">({stats.collections[col]})</span>
                )}
              </button>
            ))}
          </div>

          {/* View and Actions buttons */}
          <div className="flex items-center gap-2">
            <div className="inline-flex rounded-lg border border-border/60 bg-muted/30 p-0.5 text-xs">
              <button
                type="button"
                onClick={() => setViewMode("table")}
                className={`rounded-md px-2.5 py-1 font-medium transition-all ${
                  viewMode === "table" ? "bg-background text-foreground shadow-xs" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                Table View
              </button>
              <button
                type="button"
                onClick={() => setViewMode("json")}
                className={`rounded-md px-2.5 py-1 font-medium transition-all ${
                  viewMode === "json" ? "bg-background text-foreground shadow-xs" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                JSON Tree
              </button>
            </div>

            <Button variant="outline" size="sm" onClick={handleExportJson} title="Export collection as JSON">
              <Download className="size-3.5 mr-1" /> JSON
            </Button>
            <Button variant="outline" size="sm" onClick={handleExportCsv} title="Export collection as CSV">
              <FileSpreadsheet className="size-3.5 mr-1" /> CSV
            </Button>
          </div>
        </div>

        {/* Search, Filter & Sort Toolbar */}
        <div className="grid grid-cols-1 gap-2 sm:grid-cols-4">
          <div className="relative sm:col-span-2">
            <Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" />
            <input
              type="text"
              className="w-full rounded-lg border border-input bg-background/80 pl-9 pr-3 py-1.5 text-xs outline-none focus:ring-2 focus:ring-ring placeholder:text-muted-foreground"
              placeholder={`Search in ${activeCollection}...`}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex items-center gap-1.5">
            <Filter className="size-3.5 text-muted-foreground shrink-0" />
            <select
              className="w-full rounded-lg border border-input bg-background/80 px-2.5 py-1.5 text-xs font-medium outline-none focus:ring-2 focus:ring-ring"
              value={priorityFilter}
              onChange={(e) => setPriorityFilter(e.target.value)}
            >
              <option value="all">All Priorities</option>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
          </div>

          <div className="flex items-center gap-1.5">
            <ArrowUpDown className="size-3.5 text-muted-foreground shrink-0" />
            <select
              className="w-full rounded-lg border border-input bg-background/80 px-2.5 py-1.5 text-xs font-medium outline-none focus:ring-2 focus:ring-ring"
              value={`${sortField}-${sortOrder}`}
              onChange={(e) => {
                const [f, o] = e.target.value.split("-");
                setSortField(f);
                setSortOrder(o as "asc" | "desc");
              }}
            >
              <option value="createdAt-desc">Newest First</option>
              <option value="createdAt-asc">Oldest First</option>
              <option value="title-asc">Title (A-Z)</option>
              <option value="title-desc">Title (Z-A)</option>
            </select>
          </div>
        </div>

        {/* Input Bar */}
        <div className="flex flex-col sm:flex-row gap-2">
          <input
            type="text"
            className="flex-1 rounded-lg border border-input bg-background/90 px-3.5 py-2 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring placeholder:text-muted-foreground select-text"
            placeholder={`Add a new record to '${activeCollection}'...`}
            value={newTitle}
            onChange={(e) => setNewTitle(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") void handleCreate();
            }}
          />

          <select
            className="rounded-lg border border-input bg-background/90 px-3 py-2 text-xs font-medium shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
            value={newPriority}
            onChange={(e) => setNewPriority(e.target.value as "low" | "medium" | "high")}
          >
            <option value="low">Low Priority</option>
            <option value="medium">Medium Priority</option>
            <option value="high">High Priority</option>
          </select>

          <Button type="button" disabled={!newTitle.trim()} onClick={handleCreate} className="shrink-0">
            <Plus className="size-4 mr-1.5" /> Add Record
          </Button>

          <Button type="button" variant="outline" onClick={handleInsertSeedData} className="shrink-0" title="Add 4 demo records">
            <Sparkles className="size-3.5 mr-1.5 text-amber-500" /> Insert Seed
          </Button>
        </div>

        {/* Content View: Table vs JSON */}
        {viewMode === "json" ? (
          <div className="rounded-xl border border-border/80 bg-black/70 p-4 font-mono text-xs text-emerald-400 space-y-2">
            <div className="flex items-center justify-between text-muted-foreground pb-2 border-b border-border/40">
              <span className="flex items-center gap-2">
                <FileJson className="size-4 text-primary" /> Live {activeCollection} Collection ({items.length} items)
              </span>
              <span className="text-[10px] text-muted-foreground">Auto-updates on any disk mutation</span>
            </div>
            <pre className="max-h-96 overflow-y-auto whitespace-pre-wrap select-text">
              {JSON.stringify(items, null, 2)}
            </pre>
          </div>
        ) : (
          <div className="space-y-2">
            {loading ? (
              <div className="py-12 text-center text-xs text-muted-foreground animate-pulse">
                Loading collection &apos;{activeCollection}&apos;...
              </div>
            ) : items.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-border/80 p-12 text-center space-y-3">
                <Database className="size-10 mx-auto text-muted-foreground/40" />
                <p className="text-sm font-semibold text-foreground">Collection &apos;{activeCollection}&apos; is empty</p>
                <p className="text-xs text-muted-foreground max-w-sm mx-auto">
                  Insert your first item using the input above or click &apos;Insert Seed&apos; to load sample documents.
                </p>
                <Button variant="outline" size="sm" onClick={handleInsertSeedData}>
                  <Sparkles className="size-3.5 mr-1.5 text-amber-500" /> Load Sample Data
                </Button>
              </div>
            ) : (
              <div className="space-y-2 max-h-96 overflow-y-auto pr-1">
                {items.map((item: any) => (
                  <div
                    key={item.id}
                    className={`flex items-center justify-between rounded-xl border p-3 transition-all ${
                      item.completed
                        ? "bg-muted/30 border-border/40 opacity-75"
                        : "bg-background/80 border-border/80 hover:border-primary/50 shadow-xs"
                    }`}
                  >
                    <div className="flex items-center gap-3 min-w-0 flex-1 mr-3">
                      <button
                        type="button"
                        onClick={() => void handleToggle(item)}
                        className="text-muted-foreground hover:text-primary transition-colors shrink-0"
                        title={item.completed ? "Mark active" : "Mark completed"}
                      >
                        {item.completed ? (
                          <CheckCircle2 className="size-5 text-emerald-500" />
                        ) : (
                          <Circle className="size-5" />
                        )}
                      </button>

                      <div className="min-w-0 flex-1">
                        <p
                          className={`text-sm font-medium truncate ${
                            item.completed ? "line-through text-muted-foreground" : "text-foreground"
                          }`}
                        >
                          {item.title || item.name || item.text || JSON.stringify(item)}
                        </p>
                        <div className="flex flex-wrap items-center gap-2 mt-1 text-[10px] text-muted-foreground font-mono">
                          <span className="bg-muted/70 px-1.5 py-0.2 rounded">{item.id}</span>
                          {item.priority && (
                            <span
                              className={`rounded px-1.5 py-0.2 font-semibold uppercase text-[9px] ${
                                item.priority === "high"
                                  ? "bg-rose-500/10 text-rose-500 border border-rose-500/20"
                                  : item.priority === "medium"
                                  ? "bg-amber-500/10 text-amber-500 border border-amber-500/20"
                                  : "bg-sky-500/10 text-sky-500 border border-sky-500/20"
                              }`}
                            >
                              {item.priority}
                            </span>
                          )}
                          {item.source && (
                            <span className="rounded bg-primary/10 text-primary px-1.5 py-0.2 font-sans font-medium">
                              {item.source}
                            </span>
                          )}
                          <span>{item.createdAt ? new Date(item.createdAt).toLocaleTimeString() : ""}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-1 shrink-0">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="size-8 text-muted-foreground hover:text-destructive"
                        onClick={() => void handleDelete(item.id, item.title)}
                        title="Delete item"
                      >
                        <Trash2 className="size-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Collection Summary & Clear button */}
        <div className="flex items-center justify-between pt-2 border-t border-border/40 text-xs text-muted-foreground">
          <span>
            Showing <strong className="text-foreground">{items.length}</strong> {items.length === 1 ? "record" : "records"} in <code className="text-primary font-semibold">{activeCollection}</code>
          </span>
          {items.length > 0 && (
            <button
              type="button"
              onClick={handleClearCollection}
              className="text-xs text-muted-foreground hover:text-destructive transition-colors"
            >
              Clear collection
            </button>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

