import {
  app,
  BrowserWindow,
  dialog,
  ipcMain,
  shell,
  Notification,
  clipboard,
  nativeTheme,
} from "electron";
import path from "node:path";
import fs from "node:fs";
import { spawn, spawnSync } from "node:child_process";
import net from "node:net";
import type { ChildProcess } from "node:child_process";
import { initDatabase } from "./database";

// Handle Squirrel installer events on Windows directly without external dependencies
function handleSquirrelEvent(): boolean {
  if (process.platform !== "win32") return false;
  const cmd = process.argv[1];
  const target = path.basename(process.execPath);

  const runUpdate = (args: string[]) => {
    const updateExe = path.resolve(path.dirname(process.execPath), "..", "Update.exe");
    try {
      spawn(updateExe, args, { detached: true }).on("close", () => {
        app.quit();
        process.exit(0);
      });
    } catch {
      app.quit();
      process.exit(0);
    }
  };

  if (cmd === "--squirrel-install" || cmd === "--squirrel-updated") {
    runUpdate(["--createShortcut=" + target]);
    return true;
  }
  if (cmd === "--squirrel-uninstall") {
    runUpdate(["--removeShortcut=" + target]);
    return true;
  }
  if (cmd === "--squirrel-obsolete") {
    app.quit();
    process.exit(0);
    return true;
  }
  return false;
}

if (handleSquirrelEvent()) {
  process.exit(0);
}

const isDevelopment = !app.isPackaged;
let mainWindow: BrowserWindow | null = null;
let nextServer: ChildProcess | null = null;
let desktopServerPort: number | null = null;
let serverStderrBuffer: string[] = [];

function loadDesktopConfig() {
  const possiblePaths = [
    path.join(app.getAppPath(), "desktop.config.json"),
    path.join(process.cwd(), "desktop.config.json"),
    path.join(__dirname, "..", "desktop.config.json"),
  ];
  for (const p of possiblePaths) {
    if (fs.existsSync(p)) {
      try {
        return JSON.parse(fs.readFileSync(p, "utf8"));
      } catch {}
    }
  }
  return {
    app: { name: "Nextron", slug: "nextron", version: "1.0.0" },
    window: {
      width: 1280,
      height: 840,
      minWidth: 920,
      minHeight: 620,
      backgroundColor: "#090d16",
      frame: false,
      resizable: true,
      maximizable: true,
      minimizable: true,
      center: true,
    },
  };
}

const desktopConfig = loadDesktopConfig();
const isInitMode = process.argv.includes("--init") || process.env.NEXTRON_INIT_MODE === "1";

async function createInitializerWindow(): Promise<void> {
  const initWindow = new BrowserWindow({
    width: 980,
    height: 720,
    minWidth: 800,
    minHeight: 600,
    backgroundColor: "#090d16",
    title: "Nextron Desktop Project Initializer",
    webPreferences: {
      preload: path.join(__dirname, "initializer-preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  initWindow.setMenuBarVisibility(false);
  const htmlPath = path.join(__dirname, "initializer.html");
  if (fs.existsSync(htmlPath)) {
    await initWindow.loadFile(htmlPath);
  } else {
    await initWindow.loadFile(path.join(app.getAppPath(), "electron", "initializer.html"));
  }
}

const hasSingleInstanceLock = app.requestSingleInstanceLock();
if (!hasSingleInstanceLock) {
  app.quit();
  process.exit(0);
}

/**
 * Resolves and ensures the database directory inside the application directory (app.getAppPath()).
 * Works automatically in development, packaged app (.asar), and handles permissions.
 */
function getDatabaseDir(): string {
  if (process.env.DATABASE_DIR) return process.env.DATABASE_DIR;

  let baseDir: string;
  try {
    const appPath = app.getAppPath();
    if (!app.isPackaged && !appPath.endsWith(".asar")) {
      baseDir = path.join(appPath, "data");
    } else {
      const resourcesDir = path.dirname(appPath);
      baseDir = path.join(resourcesDir, "data");
    }

    if (!fs.existsSync(baseDir)) {
      fs.mkdirSync(baseDir, { recursive: true });
    }
    fs.accessSync(baseDir, fs.constants.W_OK);
    return baseDir;
  } catch {
    const fallback = path.join(app.getPath("userData"), "data");
    if (!fs.existsSync(fallback)) {
      fs.mkdirSync(fallback, { recursive: true });
    }
    return fallback;
  }
}

// Initialize database in the application directory
const dbDir = getDatabaseDir();
process.env.DATABASE_DIR = dbDir;
const db = initDatabase({ dataDir: dbDir });

function findAvailablePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const probe = net.createServer();
    probe.once("error", reject);
    probe.listen(0, "127.0.0.1", () => {
      const address = probe.address();
      const port =
        typeof address === "object" && address ? address.port : null;
      probe.close((error) => (error ? reject(error) : resolve(port!)));
    });
  });
}

function stopServer(): void {
  if (nextServer && nextServer.pid) {
    const pid = nextServer.pid;
    nextServer = null;
    if (process.platform === "win32") {
      try {
        spawnSync("taskkill", ["/pid", String(pid), "/T", "/F"], {
          stdio: "ignore",
        });
      } catch {
        // Fallback
      }
    } else {
      try {
        process.kill(pid, "SIGTERM");
      } catch {
        // Fallback
      }
    }
  }
}

async function startPackagedNextServer(): Promise<void> {
  const serverDirectory = path.join(process.resourcesPath, "standalone");
  const serverFile = path.join(serverDirectory, "server.js");

  if (!fs.existsSync(serverFile)) {
    throw new Error(
      `Packaged Next.js standalone server is missing at:\n${serverFile}`
    );
  }

  desktopServerPort = await findAvailablePort();
  serverStderrBuffer = [];

  nextServer = spawn(process.execPath, [serverFile], {
    cwd: serverDirectory,
    env: {
      ...process.env,
      ELECTRON_RUN_AS_NODE: "1",
      HOSTNAME: "127.0.0.1",
      PORT: String(desktopServerPort),
      NODE_ENV: "production",
      DATABASE_DIR: dbDir,
    },
    stdio: ["ignore", "pipe", "pipe"],
  });

  nextServer.stdout?.on("data", (chunk: Buffer) => {
    if (isDevelopment) process.stdout.write(chunk);
  });

  nextServer.stderr?.on("data", (chunk: Buffer) => {
    const text = chunk.toString();
    if (isDevelopment) process.stderr.write(chunk);
    serverStderrBuffer.push(text);
    if (serverStderrBuffer.length > 30) serverStderrBuffer.shift();
  });

  nextServer.once("exit", (code, signal) => {
    if (nextServer) {
      console.warn(
        `Next.js server exited unexpectedly with code ${code}, signal ${signal}`
      );
      nextServer = null;
    }
  });
}

function waitForPackagedServer(retries = 100): Promise<void> {
  return new Promise((resolve, reject) => {
    let resolved = false;

    const startupError = (error: Error) => {
      if (resolved) return;
      resolved = true;
      const recentErrors = serverStderrBuffer.join("\n").trim();
      const detailedMessage = recentErrors
        ? `${error.message}\n\nServer Output:\n${recentErrors}`
        : error.message;
      reject(new Error(detailedMessage));
    };

    const serverExit = (code: number | null, signal: string | null) => {
      startupError(
        new Error(
          `The packaged Next.js server stopped during startup (code: ${
            code ?? "unknown"
          }, signal: ${signal ?? "none"}).`
        )
      );
    };

    nextServer?.once("error", startupError);
    nextServer?.once("exit", serverExit);

    const attempt = () => {
      if (resolved) return;
      const socket = net.connect(desktopServerPort!, "127.0.0.1");

      socket.once("connect", () => {
        resolved = true;
        socket.end();
        nextServer?.removeListener("error", startupError);
        nextServer?.removeListener("exit", serverExit);
        resolve();
      });

      socket.once("error", () => {
        socket.destroy();
        if (retries-- <= 0) {
          startupError(
            new Error("The packaged Next.js server timed out during initialization.")
          );
        } else {
          setTimeout(attempt, 150);
        }
      });
    };

    attempt();
  });
}

async function createWindow(): Promise<void> {
  if (!isDevelopment && !nextServer) {
    await startPackagedNextServer();
    await waitForPackagedServer();
  }

  mainWindow = new BrowserWindow({
    width: desktopConfig.window?.width || 1280,
    height: desktopConfig.window?.height || 840,
    minWidth: desktopConfig.window?.minWidth || 920,
    minHeight: desktopConfig.window?.minHeight || 620,
    backgroundColor: desktopConfig.window?.backgroundColor || "#090d16",
    titleBarStyle: desktopConfig.window?.frame
      ? "default"
      : process.platform === "darwin"
      ? "hiddenInset"
      : "hidden",
    frame: Boolean(desktopConfig.window?.frame),
    resizable: desktopConfig.window?.resizable ?? true,
    maximizable: desktopConfig.window?.maximizable ?? true,
    minimizable: desktopConfig.window?.minimizable ?? true,
    center: desktopConfig.window?.center ?? true,
    title: desktopConfig.window?.title || desktopConfig.app?.name || "Nextron Desktop",
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  mainWindow.setMenuBarVisibility(false);
  mainWindow.setAutoHideMenuBar(true);

  // Send maximize/unmaximize state changes to renderer for custom title bar
  mainWindow.on("maximize", () => {
    mainWindow?.webContents.send("desktop:window:maximize-change", true);
  });
  mainWindow.on("unmaximize", () => {
    mainWindow?.webContents.send("desktop:window:maximize-change", false);
  });

  if (isDevelopment) {
    await mainWindow.webContents.session.clearCache();
    mainWindow.webContents.session.webRequest.onBeforeSendHeaders(
      (details, callback) => {
        details.requestHeaders["Cache-Control"] =
          "no-cache, no-store, must-revalidate";
        details.requestHeaders["Pragma"] = "no-cache";
        callback({ requestHeaders: details.requestHeaders });
      }
    );

    await mainWindow.loadURL("http://127.0.0.1:3000");
  } else {
    await mainWindow.loadURL(`http://127.0.0.1:${desktopServerPort}`);
  }
}

async function handleStartupFailure(error: unknown): Promise<void> {
  console.error("Unable to start the desktop application.", error);
  await dialog.showMessageBox({
    type: "error",
    title: "Application Startup Error",
    message: "The local desktop server could not be started.",
    detail: error instanceof Error ? error.message : String(error),
  });
  stopServer();
  app.quit();
}

app
  .whenReady()
  .then(async () => {
    if (!hasSingleInstanceLock) return;

    if (isInitMode) {
      ipcMain.handle("initializer:pick-folder", async () => {
        const res = await dialog.showOpenDialog({
          title: "Select Project Destination Folder",
          properties: ["openDirectory", "createDirectory"],
        });
        if (res.canceled || res.filePaths.length === 0) return null;
        return res.filePaths[0];
      });

      ipcMain.handle("initializer:start", async (event, payload) => {
        try {
          const scaffoldModule = await import(path.join(app.getAppPath(), "scripts", "scaffold.mjs"));
          const sourceDir = app.getAppPath();
          return await scaffoldModule.scaffoldProject({
            sourceDir,
            targetDir: payload.targetDir,
            config: payload.config,
            installDeps: payload.installDeps,
            onLog: (msg: string) => event.sender.send("initializer:log", msg),
            onProgress: (pct: number, step: string) =>
              event.sender.send("initializer:progress", pct, step),
          });
        } catch (err: any) {
          return { success: false, error: err.message };
        }
      });

      ipcMain.handle("initializer:open-folder", (_event, dirPath: string) => {
        shell.openPath(dirPath);
      });

      ipcMain.handle("initializer:open-vscode", (_event, dirPath: string) => {
        spawn("code", [dirPath], { shell: true });
      });

      await createInitializerWindow();
      return;
    }

    // General System IPC
    ipcMain.handle("desktop:get-version", () => app.getVersion());
    ipcMain.handle("desktop:get-platform", () => process.platform);
    ipcMain.handle("desktop:get-config", () => desktopConfig);

    ipcMain.handle("desktop:open-external", async (_event, url: string) => {
      const target = new URL(url);
      if (target.protocol !== "https:" && target.protocol !== "http:") {
        throw new Error("Only HTTP(S) links may be opened from the app.");
      }
      await shell.openExternal(target.toString());
    });

    // Window Controls IPC
    ipcMain.handle("desktop:window:minimize", () => {
      mainWindow?.minimize();
    });
    ipcMain.handle("desktop:window:maximize", () => {
      mainWindow?.maximize();
    });
    ipcMain.handle("desktop:window:unmaximize", () => {
      mainWindow?.unmaximize();
    });
    ipcMain.handle("desktop:window:toggle-maximize", () => {
      if (mainWindow) {
        if (mainWindow.isMaximized()) {
          mainWindow.unmaximize();
        } else {
          mainWindow.maximize();
        }
        return mainWindow.isMaximized();
      }
      return false;
    });
    ipcMain.handle("desktop:window:is-maximized", () => {
      return mainWindow ? mainWindow.isMaximized() : false;
    });
    ipcMain.handle("desktop:window:close", () => {
      mainWindow?.close();
    });
    ipcMain.handle(
      "desktop:window:set-always-on-top",
      (_event, flag: boolean) => {
        if (mainWindow) {
          mainWindow.setAlwaysOnTop(Boolean(flag));
          return mainWindow.isAlwaysOnTop();
        }
        return false;
      }
    );
    ipcMain.handle("desktop:window:is-always-on-top", () => {
      return mainWindow ? mainWindow.isAlwaysOnTop() : false;
    });

    // Native Dialogs IPC
    ipcMain.handle(
      "desktop:dialog:open",
      async (_event, options: Electron.OpenDialogOptions) => {
        if (!mainWindow) return { canceled: true, filePaths: [] };
        return await dialog.showOpenDialog(mainWindow, options || {});
      }
    );
    ipcMain.handle(
      "desktop:dialog:save",
      async (_event, options: Electron.SaveDialogOptions) => {
        if (!mainWindow) return { canceled: true };
        return await dialog.showSaveDialog(mainWindow, options || {});
      }
    );
    ipcMain.handle(
      "desktop:dialog:message",
      async (_event, options: Electron.MessageBoxOptions) => {
        if (!mainWindow)
          return { response: 0, checkboxChecked: false };
        return await dialog.showMessageBox(mainWindow, options);
      }
    );

    // Native Notifications IPC
    ipcMain.handle(
      "desktop:notification:show",
      (
        _event,
        title: string,
        body: string,
        options: Electron.NotificationConstructorOptions
