    ipcMain.handle(
      "desktop:shell:show-item",
      (_event, fullPath: string) => {
        shell.showItemInFolder(fullPath);
      }
    );
    ipcMain.handle(
      "desktop:shell:open-path",
      async (_event, fullPath: string) => {
        return await shell.openPath(fullPath);
      }
    );
