import fs from "node:fs";
import path from "node:path";

const rootDir = process.cwd();

const IGNORED_DIRS = new Set([
  ".git",
  "node_modules",
  ".next",
  "out",
  "dist",
  ".turbo",
]);

const IGNORED_FILES = new Set([
  "tsconfig.tsbuildinfo",
  "template-archive.json",
  "package-lock.json", // Optional: keep or regenerate, but let's include or exclude? We can include it or let npm install generate it. Let's include it so exact versions are locked!
]);

const BINARY_EXTENSIONS = new Set([
  ".png",
  ".ico",
  ".icns",
  ".jpg",
  ".jpeg",
  ".webp",
  ".woff",
  ".woff2",
  ".ttf",
]);

export function buildTemplateArchive() {
  const archive = {};

  function scan(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      if (IGNORED_DIRS.has(entry.name)) continue;
      if (IGNORED_FILES.has(entry.name)) continue;

      const fullPath = path.join(dir, entry.name);
      const relPath = path.relative(rootDir, fullPath).replace(/\\/g, "/");

      // Skip temporary or backup files in data/backups
      if (relPath.startsWith("data/backups/")) continue;
      if (relPath.startsWith("dist/")) continue;

      if (entry.isDirectory()) {
        scan(fullPath);
      } else {
        const ext = path.extname(entry.name).toLowerCase();
        if (BINARY_EXTENSIONS.has(ext)) {
          archive[relPath] = {
            encoding: "base64",
            content: fs.readFileSync(fullPath).toString("base64"),
          };
        } else {
          archive[relPath] = {
            encoding: "utf8",
            content: fs.readFileSync(fullPath, "utf8"),
          };
        }
      }
    }
  }

  scan(rootDir);
  return archive;
}

// If run directly via CLI
if (process.argv[1] && process.argv[1].endsWith("create-template-archive.mjs")) {
  const archive = buildTemplateArchive();
  const fileCount = Object.keys(archive).length;
  const outPath = path.join(rootDir, "template-archive.json");
  fs.writeFileSync(outPath, JSON.stringify(archive, null, 2), "utf8");
  console.log(`[template-archive] Packed ${fileCount} files into template-archive.json (${(fs.statSync(outPath).size / 1024).toFixed(1)} KB)`);
}

scripts/init-cli.mjs.content:
import readline from "node:readline";
import path from "node:path";
import fs from "node:fs";
import { scaffoldProject } from "./scaffold.mjs";

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const question = (query, defaultValue) =>
  new Promise((resolve) => {
    rl.question(`${query} ${defaultValue ? `(${defaultValue}): ` : ": "}`, (answer) => {
      resolve(answer.trim() || defaultValue || "");
    });
  });

async function run() {
  console.log("\n=======================================================");
  console.log("  🚀 Nextron Desktop App Initializer (CLI)");
  console.log("  Scaffold a new Next.js 16 + Electron app anywhere!");
  console.log("=======================================================\n");

  const appName = await question("Application Name", "My Desktop App");
  const defaultSlug = appName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  const appSlug = await question("App Slug (folder name)", defaultSlug);
  const targetDirInput = await question("Target Directory", path.resolve(process.cwd(), "..", appSlug));
  const appDesc = await question("Description", "A production desktop application built with Next.js 16 and Electron");
  const authorName = await question("Author Name", "Developer");
  const authorEmail = await question("Author Email", "dev@example.com");
  const bundleId = await question("Bundle ID", `com.${appSlug}.desktop`);
  const installDepsStr = await question("Run 'npm install' automatically? (y/n)", "y");

  const installDeps = installDepsStr.toLowerCase().startsWith("y");

  const config = {
    app: {
      name: appName,
      slug: appSlug,
      version: "1.0.0",
      description: appDesc,
      author: {
        name: authorName,
        email: authorEmail,
      },
      bundleId,
      category: "public.app-category.developer-tools",
    },
    window: {
      title: appName,
      width: 1280,
      height: 840,
      minWidth: 920,
      minHeight: 620,
      backgroundColor: "#090d16",
      titleBarStyle: "hidden",
      frame: false,
      resizable: true,
      maximizable: true,
      minimizable: true,
      center: true,
    },
    database: {
      filename: "db.json",
      autoBackup: true,
      backupIntervalMinutes: 60,
    },
    build: {
      icon: "./public/icon",
      copyright: `Copyright © ${new Date().getFullYear()} ${authorName}`,
      windows: {
        productName: appName,
        executableName: appSlug,
        setupExe: `${appName.replace(/\s+/g, "")}-Setup.exe`,
      },
      linux: {
        maintainer: `${authorName} <${authorEmail}>`,
        section: "utils",
      },
    },
  };

  console.log("\n⚙️ Scaffolding your project...");

  const sourceDir = process.cwd();
  const result = await scaffoldProject({
    sourceDir,
    targetDir: targetDirInput,
    config,
    installDeps,
    onLog: (msg) => console.log(`  ${msg}`),
    onProgress: (pct, step) => console.log(`[${pct}%] ${step}`),
  });

  if (result.success) {
    console.log("\n=======================================================");
    console.log("  🎉 Project Successfully Initialized!");
    console.log(`  Path: ${result.projectPath}`);
    console.log("=======================================================\n");
    console.log("To get started:");
    console.log(`  cd "${path.relative(process.cwd(), result.projectPath)}"`);
    if (!installDeps) {
      console.log("  npm install");
    }
    console.log("  npm run dev\n");
  } else {
    console.error(`\n❌ Failed to scaffold project: ${result.error}`);
  }

  rl.close();
}

run();

scripts/prepare-desktop.mjs.content:
import { cp, mkdir, rm } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";

const standalone = path.join(".next", "standalone");
const nextDestination = path.join(standalone, ".next", "static");

if (!existsSync(standalone)) {
  console.warn("prepare-desktop: .next/standalone does not exist yet. Run 'next build' first.");
  process.exit(0);
}

// Next intentionally leaves these assets outside standalone output. Electron needs
// them inside the server directory so the packaged app can serve them at runtime.
await rm(nextDestination, { recursive: true, force: true });
await mkdir(path.dirname(nextDestination), { recursive: true });

if (existsSync(path.join(".next", "static"))) {
  await cp(path.join(".next", "static"), nextDestination, { recursive: true });
}

if (existsSync("public")) {
  await cp("public", path.join(standalone, "public"), { recursive: true, force: true });
}

scripts/scaffold.mjs.content:
import fs from "node:fs";
import path from "node:path";
import { exec } from "node:child_process";
import { promisify } from "node:util";

const execAsync = promisify(exec);

const IGNORED_PATHS = new Set([
  ".git",
  "node_modules",
  ".next",
  "out",
  ".turbo",
  "tsconfig.tsbuildinfo",
]);

function copyDirRecursive(src, dest, onFile) {
  if (!fs.existsSync(dest)) {
    fs.mkdirSync(dest, { recursive: true });
  }

  const entries = fs.readdirSync(src, { withFileTypes: true });

  for (const entry of entries) {
    if (IGNORED_PATHS.has(entry.name)) continue;

    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      copyDirRecursive(srcPath, destPath, onFile);
    } else {
      fs.copyFileSync(srcPath, destPath);
      if (onFile) onFile(entry.name);
    }
  }
}

export async function scaffoldProject({
  sourceDir,
  targetDir,
  config,
  installDeps = false,
  onLog = () => {},
  onProgress = () => {},
}) {
  try {
    const finalProjectDir = path.isAbsolute(targetDir)
      ? targetDir
      : path.resolve(process.cwd(), targetDir);

    onProgress(15, `Creating destination directory: ${finalProjectDir}`);
    if (!fs.existsSync(finalProjectDir)) {
      fs.mkdirSync(finalProjectDir, { recursive: true });
    }

    onProgress(30, "Copying core Nextron desktop kit template files...");
    copyDirRecursive(sourceDir, finalProjectDir, (file) => {
      onLog(`Copied: ${file}`);
    });

    onProgress(60, "Writing customized desktop.config.json...");
    const configPath = path.join(finalProjectDir, "desktop.config.json");
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2) + "\n", "utf8");

    onProgress(70, "Synchronizing package.json metadata...");
    const pkgPath = path.join(finalProjectDir, "package.json");
    if (fs.existsSync(pkgPath)) {
      const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
      pkg.name = config.app?.slug || "my-desktop-app";
      pkg.version = config.app?.version || "1.0.0";
      pkg.description = config.app?.description || "";
      if (config.app?.author) {
        pkg.author = `${config.app.author.name || "Developer"}${
          config.app.author.email ? ` <${config.app.author.email}>` : ""
        }`;
      }
      fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + "\n", "utf8");
    }

    onProgress(80, "Initializing fresh real-time database in data/db.json...");
    const dataDir = path.join(finalProjectDir, "data");
    if (!fs.existsSync(dataDir)) {
      fs.mkdirSync(dataDir, { recursive: true });
    }
    const dbFile = path.join(dataDir, "db.json");
    const initialDb = {
      _meta: {
        version: 2,
        rev: 1,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      },
      todos: [
        {
          id: `todo_${Date.now().toString(36)}_init`,
          title: "Welcome to your new Nextron Desktop App!",
          completed: false,
          priority: "high",
          source: "Nextron Initializer",
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
      ],
    };
    fs.writeFileSync(dbFile, JSON.stringify(initialDb, null, 2) + "\n", "utf8");

    if (installDeps) {
      onProgress(85, "Installing dependencies via npm (this may take a minute)...");
      onLog("Running: npm install in " + finalProjectDir);
      try {
        await execAsync("npm install", { cwd: finalProjectDir });
        onLog("npm install completed successfully.");
      } catch (npmErr) {
        onLog(`Warning: npm install had notice: ${npmErr.message}`);
      }
    }

    onProgress(100, "Project scaffolded successfully! ✨");
    return {
      success: true,
      projectPath: finalProjectDir,
    };
  } catch (err) {
    onLog(`Error during scaffolding: ${err.message}`);
    return {
      success: false,
      error: err.message,
    };
  }
}

scripts/sync-config.mjs.content:
import fs from "node:fs";
import path from "node:path";

const rootDir = process.cwd();
const configPath = path.join(rootDir, "desktop.config.json");
const packageJsonPath = path.join(rootDir, "package.json");

if (!fs.existsSync(configPath)) {
  console.warn("[sync-config] desktop.config.json not found, skipping sync.");
  process.exit(0);
}

try {
  const desktopConfig = JSON.parse(fs.readFileSync(configPath, "utf8"));
  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));

  let changed = false;

  if (desktopConfig.app?.slug && packageJson.name !== desktopConfig.app.slug) {
    packageJson.name = desktopConfig.app.slug;
    changed = true;
  }

  if (desktopConfig.app?.version && packageJson.version !== desktopConfig.app.version) {
    packageJson.version = desktopConfig.app.version;
    changed = true;
  }

  if (desktopConfig.app?.description && packageJson.description !== desktopConfig.app.description) {
    packageJson.description = desktopConfig.app.description;
    changed = true;
  }

  const authorStr = desktopConfig.app?.author
    ? `${desktopConfig.app.author.name || "Developer"}${
        desktopConfig.app.author.email ? ` <${desktopConfig.app.author.email}>` : ""
      }`
    : packageJson.author;

  if (authorStr && packageJson.author !== authorStr) {
    packageJson.author = authorStr;
    changed = true;
  }

  if (changed) {
    fs.writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2) + "\n", "utf8");
    console.log("[sync-config] Synchronized package.json from desktop.config.json successfully.");
  }
} catch (err) {
  console.error("[sync-config] Failed to sync config:", err);
}

